import{_ as e,o as r,c as t,a2 as n}from"./chunks/framework.BZO4qERu.js";const c=JSON.parse('{"title":"Интеграции","description":"","frontmatter":{},"headers":[],"relativePath":"ru/integrations/index.md","filePath":"ru/integrations/index.md","lastUpdated":1792323081000}'),i={name:"ru/integrations/index.md"};function o(s,a,l,h,g,d){return r(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="интеграции" tabindex="-1">Интеграции <a class="header-anchor" href="#интеграции" aria-label="Permalink to &quot;Интеграции&quot;">​</a></h1><p>Интеграции связывают Memoh с внешними системами. Этот раздел нужен, когда вы хотите вывести Bot в чат-платформы или настроить провайдеров моделей, памяти, речи или поиска.</p><h2 id="каналы" tabindex="-1">Каналы <a class="header-anchor" href="#каналы" aria-label="Permalink to &quot;Каналы&quot;">​</a></h2><p>Каналы делают Bot доступным за пределами приложения Memoh.</p><ul><li><strong><a href="/ru/integrations/channels/">Обзор каналов</a></strong>: поддерживаемые платформы и общий порядок настройки.</li><li><strong><a href="/ru/integrations/channels/slack.html">Slack</a></strong>, <strong><a href="/ru/integrations/channels/telegram.html">Telegram</a></strong>, <strong><a href="/ru/integrations/channels/feishu.html">Feishu</a></strong>, <strong><a href="/ru/integrations/channels/discord.html">Discord</a></strong>, <strong><a href="/ru/integrations/channels/weixin.html">WeChat</a></strong> и другие.</li></ul><h2 id="проваидеры" tabindex="-1">Провайдеры <a class="header-anchor" href="#проваидеры" aria-label="Permalink to &quot;Провайдеры&quot;">​</a></h2><p>Провайдеры подключают Memoh к внешним бэкендам возможностей.</p><ul><li><strong><a href="/ru/integrations/providers/llm.html">Провайдеры моделей</a></strong>: настройка вышестоящих API, client type и ролей моделей.</li><li><strong><a href="/ru/integrations/providers/memory/builtin.html">Провайдеры памяти</a></strong>: выбор между встроенной памятью, Mem0 и OpenViking.</li><li><strong><a href="/ru/integrations/providers/web-search.html">Провайдеры веб-поиска</a></strong>: настройка доступа к провайдеру поиска.</li></ul><h2 id="руководства-по-продукту" tabindex="-1">Руководства по продукту <a class="header-anchor" href="#руководства-по-продукту" aria-label="Permalink to &quot;Руководства по продукту&quot;">​</a></h2><p>Когда интеграции настроены, переходите в <strong><a href="/ru/guides/">Справочник</a></strong>: настройка Bot, сессии, работа с памятью, инструменты и повседневные сценарии работы.</p>',10)])])}const m=e(i,[["render",o]]);export{c as __pageData,m as default};
